<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$token=(string)($_GET['token']??'');$s=$db->prepare('SELECT s.*,c.name,c.company FROM client_portal_sessions s JOIN clients c ON c.id=s.client_id WHERE s.token_hash=? AND s.expires_at>NOW()');$s->execute([hash('sha256',$token)]);$session=$s->fetch();if(!$session){http_response_code(403);exit('Invalid or expired portal link.');}$q=$db->prepare("SELECT i.*,COALESCE(p.name,'') project_name FROM invoices i LEFT JOIN client_projects p ON p.id=i.project_id WHERE i.client_id=? OR (i.client_id IS NULL AND i.lead_id=?) ORDER BY i.created_at DESC");$q->execute([$session['client_id'],$session['client_id']]);$rows=$q->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Billing</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><a href="index.php?token=<?=$e(urlencode($token))?>">← Portal</a><div class="mt-3 mb-4"><h1 class="h2">Billing & Invoices</h1><p class="text-muted">Welcome, <?=$e($session['name'])?>.</p></div><div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Invoice</th><th>Project</th><th>Total</th><th>Balance</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$e($r['invoice_number'])?></td><td><?=$e($r['project_name'])?></td><td><?=$e($r['currency'])?> <?=number_format((float)$r['total'],2)?></td><td><?=$e($r['currency'])?> <?=number_format((float)$r['balance_due'],2)?></td><td><?=$e($r['status'])?></td><td><a class="btn btn-sm btn-outline-dark" href="invoice.php?token=<?=$e(urlencode($token))?>&invoice=<?=$r['id']?>">View</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="p-4 text-muted">No invoices are linked to your account.</td></tr><?php endif;?></tbody></table></div></div></main></body></html>